function modulePlan(modules, prerequisites) {
  const done = new Set();
  let progress = true;
  while (progress) {
    progress = false;
    for (let m = 0; m < modules; m++) {
      if (done.has(m)) continue;
      if (prerequisites.every(([module, needed]) => module !== m || done.has(needed))) { done.add(m); progress = true; }
    }
  }
  return done.size === modules;
}

function modulePlan(modules, prerequisites) {
  const indegree = new Array(modules).fill(0);
  const unlocks = Array.from({ length: modules }, () => []);
  for (const [module, needed] of prerequisites) { unlocks[needed].push(module); indegree[module]++; }
  const ready = [];
  for (let m = 0; m < modules; m++) if (indegree[m] === 0) ready.push(m);
  let done = 0;
  while (ready.length) {
    const m = ready.pop();
    done++;
    for (const next of unlocks[m]) if (--indegree[next] === 0) ready.push(next);
  }
  return done === modules;
}
